-- Supabase-flavoured and multi-tenant SaaS queries
SELECT * FROM profiles WHERE id = auth.uid();
SELECT * FROM public.posts p WHERE p.org_id = (current_setting('request.jwt.claims', true)::json->>'org_id')::uuid;
SELECT p.id, p.title, jsonb_build_object('id', a.id, 'name', a.name) AS author FROM posts p JOIN authors a ON a.id = p.author_id WHERE p.published = true ORDER BY p.created_at DESC LIMIT 20;
SELECT id, title, ts_headline('english', body, q) FROM posts, websearch_to_tsquery('english', 'postgres tips') AS q WHERE fts @@ q ORDER BY ts_rank_cd(fts, q) DESC;
SELECT id, embedding <=> '[0.1, 0.2, 0.3]'::vector AS distance FROM documents ORDER BY embedding <=> '[0.1, 0.2, 0.3]' LIMIT 5;
INSERT INTO storage.objects (bucket_id, name, owner) VALUES ('avatars', 'a.png', auth.uid()) RETURNING *;
UPDATE public.profiles SET metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('seen', now()) WHERE id = auth.uid();
SELECT t.id, t.name, COALESCE(json_agg(m.*) FILTER (WHERE m.id IS NOT NULL), '[]') AS members FROM teams t LEFT JOIN members m ON m.team_id = t.id GROUP BY t.id;
SELECT tenant_id, count(*) AS n, sum(amount) AS total FROM invoices WHERE issued_at >= date_trunc('quarter', current_date) GROUP BY tenant_id HAVING sum(amount) > 0 ORDER BY total DESC;
SELECT to_char(created_at, 'YYYY-MM-DD HH24:MI:SS'), to_char(total, 'FM999,999.00'), to_date('2024-01-02', 'YYYY-MM-DD'), to_timestamp(1700000000) FROM t;
SELECT lpad(id::text, 8, '0'), upper(name), left(name, 3), right(name, 2), substring(name FROM 2 FOR 3), substring(name, '[a-z]+'), position('a' IN name), overlay(name PLACING 'x' FROM 2 FOR 1), trim(BOTH ' ' FROM name), length(name), char_length(name) FROM t;
SELECT round(avg(x)::numeric, 2), ceil(x), floor(x), abs(x), mod(x, 3), power(x, 2), sqrt(x), trunc(x, 1), sign(x) FROM t;
SELECT CURRENT_DATE, CURRENT_TIME, LOCALTIMESTAMP, clock_timestamp(), statement_timestamp(), transaction_timestamp();
SELECT id FROM t WHERE name IS NULL OR name = '' OR name IN ('a', 'b') OR id NOT IN (1, 2, 3) OR created_at NOT BETWEEN '2024-01-01' AND '2024-12-31';
SELECT id, name FROM t WHERE NOT (a AND b) OR c AND NOT d;
SELECT a + b * c - d / e % f FROM t;
SELECT -x, +x, NOT flag, x IS TRUE, y IS NOT FALSE, z IS UNKNOWN FROM t;
SELECT * FROM t WHERE a = 1 AND (b = 2 OR c = 3) AND d LIKE 'x%' ESCAPE '\';
SELECT t.* FROM t JOIN u ON t.id = u.id AND u.kind = 'x' JOIN v ON v.uid = u.id WHERE t.a > 1;
SELECT t.id FROM t JOIN (SELECT id, MAX(ts) AS mx FROM log GROUP BY id) l ON l.id = t.id AND l.mx > t.updated_at;
SELECT * FROM t1 JOIN t2 USING (id) JOIN t3 USING (id, other);
SELECT COUNT(DISTINCT (a, b)) FROM t;
SELECT x FROM t GROUP BY x HAVING COUNT(*) > 1 AND MAX(y) < 10 ORDER BY x LIMIT 3;
SELECT 1 AS "select", 2 AS "order", "user", "group" FROM "table";
SELECT s.*, (s.a).field FROM s;
SELECT * FROM t WHERE x::text LIKE 'a%' AND (y)::int > 3 AND z::jsonb->>'k' = 'v';
SELECT array(SELECT id FROM t), array_to_string(ARRAY[1, 2], ','), string_to_array('a,b', ','), ARRAY(SELECT 1 UNION SELECT 2);
SELECT CASE status WHEN 'a' THEN 1 WHEN 'b' THEN 2 ELSE 0 END FROM t;
SELECT ARRAY[[1, 2], [3, 4]], '{{1,2},{3,4}}'::int[][];
